def summarize(assignments, attempts):
    passed = sum(a['status'] == 'pass' for a in attempts)
    return {'assigned': len(attempts), 'passed': passed, 'pass_rate': passed / len(attempts) if attempts else None}

def public_export(summary, attempts):
    return {'assigned': summary['assigned'], 'passed': summary['passed'], 'case_details': attempts}
